inline constexpr float FastEnemySpeed = EnemySpeed * 2.0f;
inline constexpr float FastEnemyRadius = 9.0f;
inline constexpr int FastEnemyFirstStep = 1200;
inline constexpr int FastEnemyEverySteps = 300;
inline constexpr int MaxFastEnemies = 2;

inline constexpr float CoinRadius = 10.0f;

for (auto& enemy : _enemies)
    enemy += Normalized(_player - enemy) * (EnemySpeed * step.seconds);
for (auto& enemy : _fastEnemies)
    enemy += Normalized(_player - enemy) * (FastEnemySpeed * step.seconds);
++_playSteps;
if (_playSteps >= FastEnemyFirstStep && (_playSteps - FastEnemyFirstStep) % FastEnemyEverySteps == 0
    && static_cast<int>(_fastEnemies.size()) < MaxFastEnemies)
    _fastEnemies.push_back(RandomPoint(FastEnemyRadius));

_enemies, [&](Float2 enemy) { return Distance(enemy, _player) < PlayerRadius + EnemyRadius; }) ||
std::ranges::any_of(_fastEnemies,
                    [&](Float2 enemy) { return Distance(enemy, _player) < PlayerRadius + FastEnemyRadius; });

state.Field("fastEnemies", static_cast<int>(_fastEnemies.size()));
for (std::size_t i = 0; i < _fastEnemies.size(); ++i)
    state.Group("fastEnemy", i, [&] {
        state.Field("x", _fastEnemies[i].x);
        state.Field("y", _fastEnemies[i].y);
    });
state.Field("playSteps", _playSteps);
state.Field("maxEnemies", _maxEnemies);

    paint.Circle(enemy, EnemyRadius, Fill(EnemyColor));
for (const Float2 enemy : _simulation.FastEnemies())
    paint.Circle(enemy, FastEnemyRadius, Fill(Rgb(0xff9f1a)));
